use strict;
use warnings;
use JSON::PP;
use FSM::Test::TaskAcceptanceIndexRuntime qw(run_index_case);
my $result = run_index_case('existing_source');
my $path = 'docs/audits/task-acceptance-audit-source-coverage-20261012/adapter-smoke-result.json';
open my $out, '>:raw', $path or die $!;
print {$out} JSON::PP->new->canonical->encode($result), "\n" or die $!;
close $out or die $!;
die "native checker not reached\n" unless $result->{status} eq 'checker_returned';
die "native owner refusal lost\n" unless $result->{checker}{exit_code} == 1;
